def find_multiples(factors=[3,5], min=0, max=1000):
    """Finds all numbers between min and max which are multiples of any number
       in factors"""
    def is_multiple(i):
        return any(i%x==0 for x in factors)

    return (i for i in xrange(min, max) if is_multiple(i))

