import os
import sys

def count_lines(f):
    with open(f, 'r') as f:
        return sum(1 for line in f)

def count_dir(dirname):
    counter = 0
    for root, _, files in os.walk(dirname):
        for f in files:
            count += count_lines(os.path.join(root, f))
    return counter

