import sys

def reverse(num):
    """Reverses the number

       >>> reverse(1456)
       6541
       >>> reverse(111)
       111
    """
    return int(str(num)[::-1])

def palindrome(num):
    """Return the number of iterations required to compute a palindrome

       >>> palindrome(195)
       (4, 9339)
    """
    i = 0
    while i < 100:
        rnum = reverse(num)
        if rnum == num:
            break
        num = num + rnum
        i += 1
    return (i, num)

