            return result
        else:
            path = stack.pop()
            ds, fs = partition(lambda d: isdir(join(path, d)), listdir(path))
            stack.extend(join(path, d) for d in ds)
            result.append((path, ds, fs))
            return i(result, stack)
    return i([], [expanduser(path)])

def walk_iter(path):
    stack = [expanduser(path)]
    result = []
    while stack:
        path = stack.pop()
        ds, fs = partition(lambda d: isdir(join(path, d)), listdir(path))
        stack.extend(join(path, d) for d in ds)
