    """Binary search that returns (index, low, high) of the final search step"""
    while low &lt;= high:
        mid = (low + high) // 2
        current_element = array[mid]
        if current_element == element:
            return (mid, low, high)
        elif current_element &lt; element:
            low = mid + 1
        elif current_element &gt; element:
