def partition(a, lo, hi):
    i, j, pivot = lo+1, hi, a[lo]
    while(True):
        while i < hi and a[i] < pivot:
            i += 1
        while j > lo and a[j] > pivot:
            j -= 1
        if (i >= j): break            
        a[i], a[j] = a[j], a[i]    
    a[lo], a[j] = a[j], a[lo]
    return j

def sort(a, lo, hi):
    if (hi - lo <= 0):
        return
    q = partition(a, lo, hi)
    sort(a, lo, q)
    sort(a, q+1, hi)
    assert isSorted(a, lo, hi)

