from operator import mul, pow

def repeat(f, n):
    def identity(x):
        return x

    def apply_n_times(n):
        def recursive_apply(x):
            return apply_n_times(n - 1)(f(x))

        if n < 0:
            raise ValueError("Cannot apply a function %d times" % (n))
        elif n == 0:
            return identity
        else:
            return recursive_apply
    return apply_n_times(n)

