def sum_of_pairs_matches(K, arr):
    uniques = {i: True for i in arr}
    pairs = set()
    for val in arr:
        k = -val + K if val<K else -K - val
        if(uniques.get(k, False)):
            pairs.add(tuple(sorted([k,val])))
    return pairs

