```
def sum_target(numbers, target):
    start_index = 0 # inclusive
    end_index = 0 # inclusive
    cur_sum = numbers[0]
    while end_index < len(numbers):
        if cur_sum < target:
            if end_index < len(numbers) - 1:
                end_index += 1
                cur_sum += numbers[end_index]
            else:
                return False
        elif cur_sum > target:
            cur_sum -= numbers[start_index]
            start_index += 1
        else:
            assert(cur_sum == target)
            return True

    return False
