def sumFinder(quantities, target):
    """Return a list such that dot-product(list, quantities) == target. Return None when no list is found."""
    if not quantities:
        return [] if target == 0 else None
    first, remain = quantities[0], quantities[1:]
    for i in range(target//first+1):
        found_nums = sumFinder(remain, target - first * i)
        if found_nums is not None:
            return [i] + found_nums
    return None

