def prime_sieve(limit):
    prime = [True] * limit
    prime[0] = prime[1] = False

    for i, is_prime in enumerate(prime):
        if is_prime:
            yield i
            for n in range(i * i, limit, i):
                prime[n] = False

def prime_factors(n):
    for p in prime_sieve(int(n ** 0.5) + 1):
        while n % p == 0:
            n //= p
            yield p
    if n != 1:
        yield n

