class Stack:
    def __init__(self):
        self.stack = []
        self.length = 0

    def isEmpty(self):
        return not self.stack

    def push(self, data):
        self.length += 1
        self.stack.append(data)

    def pop(self):
        self.length -= 1
        return self.stack.pop()

    def peek(self):
        return self.stack[-1]

    def sizeStack(self):
        return self.length

