def cut_log(p, n):
    global history
    ln = len(p)
    if id(p) not in history:
        p = p + [0]*max(n - ln, 0)
        for i in range(2, max(n+1, ln)):
            p[i] = max(p[i-k] + p[k] for k in range((i//2)+1))
