def dict_query(d: Dict, path: str) -> Union[object, None]:
    """
    # Example usage:
    >>> d = {'a': [{}, {'b': 9}]}
    >>> print( dict_query(d, 'a/1/b') )
    9
    """
    keys = path.split("/")
    val = d

    try:
        for key in keys:
            try:
                val = val[key]

            except (KeyError, TypeError):
                val = val[int(key)]

        return val

    except (IndexError, KeyError, TypeError, ValueError):
        return None

