Code review: Temporary queue to prevent duplication
Critique: The return handling for max queue size was simplified and a dequeue method was added. A ring buffer was suggested as a better data structure for this problem.

Revised: 
<pre><code>class TemporaryQueue:
    def __init__(self, max_items=10):
        self._queue = []
        self.max_items = max_items

    def __repr__(self):
        return "&lt;TemporaryQueue max_items={}&gt;".format(self.max_items)

    def __iter__(self):
        yield from self._queue

    def __eq__(self, other):
        return other in self._queue

    def _full(self):
        return len(self._queue) &gt;= self.max_items

    def enqueue(self, value):
        if self._full():
            self._queue.clear()

        return self._queue.append(value)

    def dequeue(self):
        return self._queue.pop()
