def countPalindromes(s):
    num_palindrome = 0

    for i in range(len(s)):
        for j in range(i + 2, len(s) + 1):
            substring = s[i: j] 
            for idx in range(len(substring)):
                if substring[idx] != substring[-idx-1]:
                    num_palindrome -= 1
                    break
            num_palindrome += 1

    return num_palindrome + len(s)

