@lru_cache(128)
def numberOfPaths(m, n):
    if m == 1 and n == 1:  # border case
        result = 1

    elif m != 1 and n != 1:
        result = numberOfPaths(m - 1, n) + numberOfPaths(m, n - 1)

    elif m != 1 and n == 1:
