class Solution {
    public int[] twoSum(int[] nums, int target) {
        int[] indices = new int[2];
        Map<Integer, Integer> map = new HashMap<>();
        for (int index = 0; index < nums.length; index++) {
            Integer value = map.get(target - nums[index]);
            if (value != null) {
                indices[1] = index;
                indices[0] = value;
                return indices;
            }
            map.put(nums[index], index);
        }
        return indices;
    }
