def greatest_factor(n):
    """ Given a natural number n, return its greatest factor below n."""
    if n % 2 == 0:
        return n // 2
    for trial_divisor in range(3, int(math.sqrt(n)) + 1, 2):
        if n % trial_divisor == 0:
            return n // trial_divisor
    return 1

